"""Write results.md from results.json, results_extra.json and embed_stats.json."""
import json
R=json.load(open("results.json")); X=json.load(open("results_extra.json")); E=json.load(open("embed_stats.json"))
mem=json.load(open("memories.json")); N=len(mem)
avg=sum(len(m["text"]) for m in mem)/N; uniq=len({m["text"] for m in mem})
M=R["machine"]; L=R["latency_k5"]; U=R["user_scoped"]; S=X["user_scoped_hit_at_5"]; B=X["binary_vec0"]; I=X["one_insert"]; Q=X["one_recall"]
pct=lambda x:f"{x*100:.1f}%"; ms=lambda x:f"{x:,.2f} ms" if x<100 else f"{x:,.0f} ms"
A,Bf,C,D,J=(R[k] for k in ["A_rows_only","B_rows_fts5","C_rows_fts5_vec0","D_rows_blob_f32","E_json_text_vector"])
vecobj=next(o for o in C["objects"] if o["name"]=="memories_vec_vector_chunks00")
memD=next(o for o in D["objects"] if o["name"]=="memories")
memJ=next(o for o in J["objects"] if o["name"]=="vectors")
ov=R["one_vector"]
o=[]; w=o.append
w("# Results\n")
w(f"Machine: {M['cpu']}, {M['ram_gb']} GB RAM, Python {M['python']}, SQLite {M['sqlite']}, sqlite-vec {M['sqlite_vec']}, fastembed with `{E['model']}` ({E['dim']}-dim, CPU). Page size {A['page_size']}.\n")
w(f"Raw numbers: `results.json`, `results_extra.json`, `embed_stats.json`. This file is generated by `report.py`.\n")
w("## Dataset\n")
w(f"- {N:,} synthetic memories from 18 templates, {U['users']} users, average {avg:.1f} characters, {uniq:,} unique texts (near-duplicates are intentional).")
w(f"- 300 paraphrased queries, one per sampled memory, generated by the same script.\n")
w("## Embedding (CPU, local)\n")
w(f"| | |\n|---|---|\n| model load | {E['load_s']:.1f} s |\n| embed {N:,} memories (batch 256) | {E['embed_10k_s']:.1f} s ({E['per_memory_ms']:.2f} ms per memory) |\n| embed one query | {E['single_query_embed_ms_median']:.1f} ms median |\n")
w("## Storage (after VACUUM)\n")
w("| variant | file bytes | bytes/memory | pages |\n|---|---|---|---|")
for name,v in [("A. rows only",A),("B. A + FTS5 (external content)",Bf),("C. B + sqlite-vec `vec0 float[384]`",C),("D. rows + float32 BLOB column",D),("E. vector as JSON text in a row",J)]:
    w(f"| {name} | {v['file_bytes']:,} | {v['bytes_per_memory']:,.1f} | {v['page_count']:,} |")
w(f"| G. sqlite-vec `bit[384]` (vectors only) | {B['file_bytes']:,} | {B['bytes_per_memory']:,.1f} | — |\n")
w(f"- vec0 adds {C['bytes_per_memory']-Bf['bytes_per_memory']:,.1f} bytes per memory; the vector chunks are {vecobj['bytes']/C['file_bytes']*100:.1f}% of store C.")
w(f"- One vector: {ov['float32_blob_bytes']:,} bytes as float32, {ov['json_text_bytes']:,} bytes as JSON text ({ov['json_text_bytes_rounded6']:,} rounded to 6 decimals).")
w(f"- Variant D: {memD['overflow_pages']} overflow pages, {memD['leaf_pages']:,} leaf pages for {N:,} rows. Variant E: {memJ['overflow_pages']:,} overflow pages, {memJ['leaf_pages']:,} leaf pages.\n")
w("## Recall latency and hit@5, k=5\n")
w(f"Query embedding is **not** included ({E['single_query_embed_ms_median']:.1f} ms median in this run).\n")
w("| method | queries | median | p95 | hit@5, global (all 10k) |\n|---|---|---|---|---|")
for k,name in [("fts5_bm25","FTS5 (bm25, OR of non-stopword terms)"),("vec0_knn","sqlite-vec vec0 KNN (float32)"),("hybrid_rrf","hybrid: FTS5 top-50 + vec0 top-50, RRF"),("blob_scan_numpy","BLOB column, read all + numpy cosine"),("json_text_scan","JSON-text vectors, read all + decode + cosine")]:
    v=L[k]; w(f"| {name} | {v['queries']} | {ms(v['median_ms'])} | {ms(v['p95_ms'])} | {pct(v['hit_at_5'])} |")
w(f"| vec0 `bit[384]` top-50 + float rerank | 300 | {ms(B['median_ms'])} | — | {pct(B['hit_at_5_with_rerank'])} |\n")
w("Global hit@5 is low because each target sits among hundreds of near-identical template siblings. Use it to compare methods, not as a quality score.\n")
w("### hit@5 scoped to the current user (~200 memories each)\n")
w(f"| method | hit@5 |\n|---|---|\n| FTS5 | {pct(S['fts5'])} |\n| vec0 | {pct(S['vec'])} |\n| hybrid (RRF) | {pct(S['hybrid'])} |\n")
w("On these paraphrased queries hybrid did not beat vector search alone.\n")
w("### Filtering after top-k\n")
w(f"- Global top 5, then drop other users' rows: {U['post_filter_avg_results_of_5']:.2f} of 5 results left on average; {pct(U['post_filter_zero_result_rate'])} of queries return nothing.")
w(f"- Filter before k (vec0 `user_id text partition key`): {U['pre_filter_avg_results_of_5']}/5 results, {ms(U['pre_filter_median_ms'])} median.\n")
w("## One insert into store C\n")
w(f"- Embedding {I['embed_ms']:.1f} ms; one transaction (row + FTS5 + vec0, default journal, synchronous=FULL) {I['insert_txn_ms']:.1f} ms.")
w(f"- {I['pages_changed']} of {I['pages_before']:,} pages changed, {I['new_pages']} added: " + ", ".join(f"{k} {v}" for k,v in I['changed_by_object'].items()) + ".")
w(f"- Query \"{Q['query']}\": vec0 returns the new memory at #1 (distance {Q['vec_top3'][0][1]:.3f}); FTS5 (`{Q['fts_query']}`) top 3: " + "; ".join(f"\"{r[1]}\"" for r in Q['fts_top3']) + ".\n")
open("results.md","w").write("\n".join(o)); print("\n".join(o))
